serialized_dashboard:
{
  "datasets": [
    {
      "name": "ds_intro_kpis",
      "displayName": "Introduction KPIs",
      "catalog": "automation_d",
      "schema": "silver",
      "config": {
        "version": "1.1",
        "source": "\n            SELECT\n              g.total_agents,\n              g.total_makers,\n              g.created_last_30d,\n              c.prepaid_credits,\n              c.prepaid_cost_eur,\n              e.payg_credits,\n              e.payg_cost_eur\n            FROM (\n              SELECT\n                MEASURE(valid_agent_count) AS total_agents,\n                MEASURE(maker_count) AS total_makers,\n                MEASURE(created_last_30d) AS created_last_30d\n              FROM automation_d.silver.metric_agent_governance_v2\n            ) g\n            CROSS JOIN (\n              SELECT\n                MEASURE(total_consumption_credits) AS prepaid_credits,\n                ROUND(MEASURE(total_consumption_cost_eur), 2) AS prepaid_cost_eur\n              FROM automation_d.silver.metric_credit_consumption_v2\n            ) c\n            CROSS JOIN (\n              SELECT\n                MEASURE(pay_as_you_go_credits) AS payg_credits,\n                ROUND(MEASURE(pay_as_you_go_credits) * (SELECT MAX(credit_to_eur) FROM automation_d.silver.ref_credit_rate), 2) AS payg_cost_eur\n              FROM automation_d.silver.metric_environment_consumption_v2\n            ) e\n            ",
        "dimensions": [],
        "measures": [
          {
            "name": "Total Agent Count",
            "expr": "MAX(total_agents)"
          },
          {
            "name": "Total Agent Makers",
            "expr": "MAX(total_makers)"
          },
          {
            "name": "Total Agents Created last 30 days",
            "expr": "MAX(created_last_30d)"
          },
          {
            "name": "Prepaid Copilot Credit Consumed",
            "expr": "MAX(prepaid_credits)"
          },
          {
            "name": "Prepaid Credit Cost (EUR)",
            "expr": "MAX(prepaid_cost_eur)"
          },
          {
            "name": "Pay-as-you-go",
            "expr": "MAX(payg_credits)"
          },
          {
            "name": "Pay-as-you-go Cost (EUR)",
            "expr": "MAX(payg_cost_eur)"
          }
        ]
      }
    },
    {
      "name": "ds_credit_split",
      "displayName": "Credit Consumption by Bucket",
      "catalog": "automation_d",
      "schema": "silver",
      "config": {
        "version": "1.1",
        "source": "\n            SELECT b.agent_category,\n                   ROUND(COALESCE(c.credits, 0), 1) AS credits,\n                   ROUND(COALESCE(c.cost_eur, 0), 2) AS cost_eur\n            FROM (\n              SELECT 'Copilot Studio' AS agent_category, 1 AS sort_order\n              UNION ALL SELECT 'Agent Builder', 2\n              UNION ALL SELECT 'Platform Tool', 3\n            ) b\n            LEFT JOIN (\n              SELECT agent_category,\n                     MEASURE(total_consumption_credits) AS credits,\n                     MEASURE(total_consumption_cost_eur) AS cost_eur\n              FROM automation_d.silver.metric_credit_consumption_v2\n              GROUP BY agent_category\n            ) c ON b.agent_category = c.agent_category\n            ORDER BY b.sort_order\n            ",
        "dimensions": [
          {
            "name": "agent_category",
            "expr": "agent_category"
          }
        ],
        "measures": [
          {
            "name": "Credits",
            "expr": "MAX(credits)"
          },
          {
            "name": "Cost (EUR)",
            "expr": "MAX(cost_eur)"
          }
        ]
      }
    },
    {
      "name": "ds_top10_agents",
      "displayName": "Top 10 Agents by Credit",
      "catalog": "automation_d",
      "schema": "silver",
      "config": {
        "version": "1.1",
        "source": "\n            SELECT agent_name,\n                   agent_category,\n                   ROUND(MEASURE(total_consumption_credits), 1) AS credits,\n                   ROUND(MEASURE(total_consumption_cost_eur), 2) AS cost_eur\n            FROM automation_d.silver.metric_credit_consumption_v2\n            WHERE agent_category <> 'Platform Tool'\n            GROUP BY agent_name, agent_category\n            ORDER BY credits DESC\n            LIMIT 10\n            ",
        "dimensions": [
          {
            "name": "agent_name",
            "expr": "agent_name"
          },
          {
            "name": "agent_category",
            "expr": "agent_category"
          }
        ],
        "measures": [
          {
            "name": "Credits",
            "expr": "MAX(credits)"
          },
          {
            "name": "Cost (EUR)",
            "expr": "MAX(cost_eur)"
          }
        ]
      }
    },
