            "name": "created_on_eu",
            "expr": "created_on_eu"
          },
          {
            "name": "platform",
            "expr": "platform"
          },
          {
            "name": "status",
            "expr": "status"
          },
          {
            "name": "authentication",
            "expr": "authentication"
          },
          {
            "name": "orchestration",
            "expr": "orchestration"
          }
        ],
        "measures": [
          {
            "name": "Agent Count",
            "expr": "COUNT(DISTINCT agent_key)"
          },
