    {
      "name": "ds_add_cost_billed_absorbed",
      "displayName": "Billed vs Absorbed Credits",
      "catalog": "automation_d",
      "schema": "silver",
      "config": {
        "version": "1.1",
        "source": "\n            SELECT 'Billed (prepaid pool)' AS category,\n                   MEASURE(billed_credits) AS credits,\n                   ROUND(MEASURE(billed_credits) * (SELECT MAX(credit_to_eur) FROM automation_d.silver.ref_credit_rate), 2) AS cost_eur\n            FROM automation_d.silver.metric_agent_feature_credit_v2\n            UNION ALL\n            SELECT 'Absorbed (license/included)',\n                   ROUND(MEASURE(non_billed_credits), 1),\n                   ROUND(MEASURE(non_billed_credits) * (SELECT MAX(credit_to_eur) FROM automation_d.silver.ref_credit_rate), 2)\n            FROM automation_d.silver.metric_agent_feature_credit_v2\n            ",
        "dimensions": [
