    {
      "name": "ds_add_cost_runrate",
      "displayName": "Projected Monthly Run-rate",
      "catalog": "automation_d",
      "schema": "silver",
      "config": {
        "version": "1.1",
        "source": "\n            SELECT\n              ROUND(SUM(prepaid_consumed_quantity) / COUNT(DISTINCT usage_date), 1) AS avg_daily_credits,\n              ROUND(SUM(prepaid_consumed_quantity) / COUNT(DISTINCT usage_date) * 30, 0) AS projected_monthly_credits,\n              ROUND(SUM(prepaid_consumed_quantity) / COUNT(DISTINCT usage_date) * 30 * (SELECT MAX(credit_to_eur) FROM automation_d.silver.ref_credit_rate), 2) AS projected_monthly_eur\n            FROM automation_d.silver.fact_environment_credit\n            ",
        "dimensions": [],
        "measures": [
          {
            "name": "Avg Daily Credits",
            "expr": "MAX(avg_daily_credits)"
          },
          {
            "name": "Projected Monthly Credits",
            "expr": "MAX(projected_monthly_credits)"
          },
          {
            "name": "Projected Monthly EUR",
            "expr": "MAX(projected_monthly_eur)"
          }
        ]
      }
    },
