        "version": "1.1",
        "source": "\n            SELECT agent_name, platform, created_by, environment_name, status,\n                   authentication, usage_status, created_on_date, created_on_eu,\n                   concat_ws(', ',\n                     CASE WHEN is_no_auth THEN 'No Auth' END,\n                     CASE WHEN NOT is_valid_agent THEN 'No Owner' END,\n                     CASE WHEN is_valid_agent AND NOT is_managed THEN 'Unmanaged Env' END,\n                     CASE WHEN is_valid_agent AND coalesce(status, '-') <> 'Available' THEN 'Draft' END) AS risk_reasons,\n                   greatest(\n                     CASE WHEN is_no_auth THEN 3 ELSE 0 END,\n                     CASE WHEN NOT is_valid_agent THEN 2 ELSE 0 END,\n                     CASE WHEN is_valid_agent AND NOT is_managed THEN 1 ELSE 0 END) AS severity\n            FROM automation_d.silver.vw_agent_governance\n            WHERE is_no_auth\n               OR (NOT is_valid_agent)\n               OR (is_valid_agent AND NOT is_managed)\n            ORDER BY severity DESC, agent_name\n            ",
