    {
      "name": "ds_consumption_declining",
      "displayName": "Bot Usage Declining Agents",
      "queryLines": [
        "WITH ref AS (\n",
        "  SELECT\n",
        "    DATE_TRUNC('MONTH', MAX(usage_date)) AS current_month\n",
        "  FROM\n",
        "    automation_d.silver.bot_usage\n",
        "),\n",
        "agent_month AS (\n",
        "  SELECT\n",
        "    bot_name,\n",
        "    DATE_TRUNC('MONTH', usage_date) AS month,\n",
        "    SUM(conversations) AS convs\n",
        "  FROM\n",
        "    automation_d.silver.bot_usage\n",
        "  GROUP BY\n",
        "    bot_name,\n",
        "    DATE_TRUNC('MONTH', usage_date)\n",
        ")\n",
        "SELECT\n",
        "  cur.bot_name,\n",
        "  prev.convs AS prior_month,\n",
        "  COALESCE(cur2.convs, 0) AS last_full_month,\n",
        "  ROUND((COALESCE(cur2.convs, 0) - prev.convs) * 100.0 / prev.convs, 1) AS change_pct\n",
        "FROM\n",
        "  (\n",
        "    SELECT DISTINCT\n",
        "      bot_name\n",
        "    FROM\n",
        "      agent_month\n",
        "  ) cur\n",
        "    CROSS JOIN ref r\n",
        "    JOIN agent_month prev\n",
        "      ON prev.bot_name = cur.bot_name\n",
        "      AND prev.month = ADD_MONTHS(r.current_month, -2)\n",
        "    LEFT JOIN agent_month cur2\n",
        "      ON cur2.bot_name = cur.bot_name\n",
        "      AND cur2.month = ADD_MONTHS(r.current_month, -1)\n",
        "WHERE\n",
        "  prev.convs >= 10\n",
        "  AND COALESCE(cur2.convs, 0) < prev.convs * 0.5\n",
        "ORDER BY\n",
        "  change_pct"
      ]
    },
    {
      "name": "ds_consumption_abandoned",
      "displayName": "Bot Usage Abandoned Agents",
      "queryLines": [
        "WITH ref AS (\n",
        "  SELECT\n",
        "    MAX(usage_date) AS max_dt\n",
        "  FROM\n",
        "    automation_d.silver.bot_usage\n",
        ")\n",
        "SELECT\n",
        "  b.bot_name,\n",
        "  SUM(b.conversations) AS lifetime_conversations,\n",
        "  COUNT(DISTINCT b.usage_date) AS lifetime_active_days,\n",
        "  MAX(b.usage_date) AS last_used,\n",
        "  DATEDIFF(r.max_dt, MAX(b.usage_date)) AS days_since_last_use\n",
        "FROM\n",
        "  automation_d.silver.bot_usage b CROSS JOIN ref r\n",
        "GROUP BY\n",
        "  b.bot_name,\n",
        "  r.max_dt\n",
        "HAVING\n",
        "  SUM(b.conversations) >= 20\n",
        "  AND MAX(b.usage_date) < DATE_SUB(r.max_dt, 60)\n",
        "ORDER BY\n",
        "  lifetime_conversations DESC"
      ]
    },
    {
      "name": "ds_consumption_mom",
      "displayName": "Bot Usage MoM Growth",
      "queryLines": [
        "WITH monthly AS (\n",
        "  SELECT\n",
        "    DATE_TRUNC('MONTH', usage_date) AS month,\n",
        "    SUM(conversations) AS convs\n",
        "  FROM\n",
        "    automation_d.silver.bot_usage\n",
        "  GROUP BY\n",
        "    DATE_TRUNC('MONTH', usage_date)\n",
        "),\n",
        "ref AS (\n",
        "  SELECT\n",
        "    DATE_TRUNC('MONTH', MAX(usage_date)) AS current_month\n",
        "  FROM\n",
        "    automation_d.silver.bot_usage\n",
        ")\n",
        "SELECT\n",
        "  prev.convs AS prior_month_conversations,\n",
        "  cur.convs AS last_full_month_conversations,\n",
        "  ROUND((cur.convs - prev.convs) * 100.0 / prev.convs, 1) AS mom_growth_pct\n",
        "FROM\n",
        "  ref r\n",
        "    JOIN monthly cur\n",
        "      ON cur.month = ADD_MONTHS(r.current_month, -1)\n",
        "    JOIN monthly prev\n",
        "      ON prev.month = ADD_MONTHS(r.current_month, -2)"
      ]
    },
    {
      "name": "ds_consumption_agent_detail",
      "displayName": "Bot Usage Agent Detail with Status",
      "queryLines": [
        "WITH ref AS (\n",
        "  SELECT\n",
        "    MAX(usage_date) AS max_dt\n",
        "  FROM\n",
        "    automation_d.silver.bot_usage\n",
        "),\n",
        "bot_status AS (\n",
        "  SELECT\n",
        "    b.bot_name,\n",
        "    CASE\n",
        "      WHEN MAX(b.usage_date) >= DATE_SUB(r.max_dt, 30) THEN 'Active (last 30 days)'\n",
        "      WHEN MAX(b.usage_date) >= DATE_SUB(r.max_dt, 60) THEN 'Idle (31-60 days)'\n",
        "      ELSE 'Dormant (60+ days)'\n",
        "    END AS usage_status,\n",
        "    MIN(b.usage_date) AS first_used,\n",
        "    MAX(b.usage_date) AS last_used,\n",
        "    DATEDIFF(r.max_dt, MAX(b.usage_date)) AS days_since_last_use,\n",
        "    COUNT(DISTINCT b.usage_date) AS active_days,\n",
        "    ROUND(AVG(b.conversations), 2) AS avg_conversations_per_bot_day\n",
        "  FROM\n",
        "    automation_d.silver.bot_usage b CROSS JOIN ref r\n",
        "  GROUP BY\n",
        "    b.bot_name,\n",
        "    r.max_dt\n",
        ")\n",
        "SELECT\n",
        "  b.bot_name,\n",
        "  b.environment,\n",
        "  CASE\n",
        "    WHEN b.environment LIKE '%PROD%' THEN 'Production'\n",
        "    WHEN LOWER(b.environment) LIKE '%default%' THEN 'Default environment'\n",
        "    ELSE 'Dev / Test / Other'\n",
        "  END AS environment_type,\n",
        "  DATE_TRUNC('MONTH', b.usage_date) AS usage_month,\n",
        "  DATE_TRUNC('QUARTER', b.usage_date) AS usage_quarter,\n",
        "  CONCAT(\n",
        "    YEAR(DATE_TRUNC('QUARTER', b.usage_date)),\n",
        "    ' Q',\n",
        "    QUARTER(DATE_TRUNC('QUARTER', b.usage_date))\n",
        "  ) AS quarter_label,\n",
        "  SUM(b.conversations) AS conversations,\n",
        "  s.usage_status,\n",
        "  s.first_used,\n",
        "  s.last_used,\n",
        "  s.days_since_last_use,\n",
        "  s.active_days,\n",
        "  s.avg_conversations_per_bot_day\n",
        "FROM\n",
        "  automation_d.silver.bot_usage b\n",
        "    JOIN bot_status s\n",
        "      ON s.bot_name = b.bot_name\n",
        "GROUP BY\n",
        "  b.bot_name,\n",
        "  b.environment,\n",
        "  DATE_TRUNC('MONTH', b.usage_date),\n",
        "  DATE_TRUNC('QUARTER', b.usage_date),\n",
        "  s.usage_status,\n",
        "  s.first_used,\n",
        "  s.last_used,\n",
        "  s.days_since_last_use,\n",
        "  s.active_days,\n",
        "  s.avg_conversations_per_bot_day"
      ]
    },
    {
